        <a href="#home">Home</a>
        <a href="#mothers">For Mothers</a>
        <a href="#children">For Children</a>
        <a href="#about">About</a>
      </div>
      <a class="button nav-cta" href="https://quickhealth-foryou.streamlit.app/">Try the demo</a>
    </nav>
  </header>

  <main>
    <section class="hero shell" id="home" aria-labelledby="hero-title">
      <div>
        <p class="eyebrow"><span class="eyebrow-dot" aria-hidden="true"></span>Built for neatHack 2026</p>
        <h1 id="hero-title">Faster, safer history-taking for mothers and children.</h1>
        <p class="hero-copy">QuickHealth helps nurses and health workers take a clear clerking history, spot danger signs early, and produce a clinician-ready note.</p>
        <div class="button-row">
          <a class="button" href="https://quickhealth-foryou.streamlit.app/">Try the demo</a>
          <a class="button button--outline" href="#how">See how it works</a>
        </div>
      </div>
      <div class="art" aria-label="A calm illustration in cream, peach and sage">
        <div class="shape shape--back" aria-hidden="true"></div>
        <div class="shape shape--peach" aria-hidden="true"></div>
        <div class="shape shape--cream" aria-hidden="true"></div>
        <div class="art-card">
          <svg viewBox="0 0 180 180" role="img" aria-label="Heart and leaf illustration" xmlns="http://www.w3.org/2000/svg">
            <path d="M90 151S27 113 27 70c0-29 37-40 63-7 26-33 63-22 63 7 0 43-63 81-63 81Z" fill="#FADBD0" stroke="#0F4C3A" stroke-width="5" stroke-linejoin="round"/>
